package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
	"time"
)

type TokenHeader struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
	Kid string `json:"kid"`
}

type TokenClaims struct {
	Sub    string `json:"sub"`
	Iss    string `json:"iss"`
	Aud    string `json:"aud"`
	Exp    int64  `json:"exp"`
	Nbf    int64  `json:"nbf"`
	Iat    int64  `json:"iat"`
	Scope  string `json:"scope"`
	Jti    string `json:"jti"`
}

type ValidationResult struct {
	Valid    bool
	Claims   *TokenClaims
	Error    string
	CachedAt time.Time
}

type KeyEntry struct {
	Secret    []byte
	Issuer    string
	Audience  string
	MaxLifetime time.Duration
}

type TokenValidator struct {
	keys       map[string]*KeyEntry
	cache      map[string]*ValidationResult
	cacheMu    sync.RWMutex
	cacheTTL   time.Duration
	clockSkew  time.Duration
}

func NewTokenValidator(cacheTTL time.Duration) *TokenValidator {
	return &TokenValidator{
		keys:      make(map[string]*KeyEntry),
		cache:     make(map[string]*ValidationResult),
		cacheTTL:  cacheTTL,
		clockSkew: 30 * time.Second,
	}
}

func (v *TokenValidator) RegisterKey(kid string, secret []byte, issuer, audience string, maxLife time.Duration) {
	v.keys[kid] = &KeyEntry{
		Secret:      secret,
		Issuer:      issuer,
		Audience:    audience,
		MaxLifetime: maxLife,
	}
}

func (v *TokenValidator) ValidateToken(rawToken string) *ValidationResult {
	// Check cache first
	v.cacheMu.RLock()
	if cached, ok := v.cache[rawToken]; ok {
		if time.Since(cached.CachedAt) < v.cacheTTL {
			v.cacheMu.RUnlock()
			return cached
		}
	}
	v.cacheMu.RUnlock()

	result := v.performValidation(rawToken)

	// Cache the result
	v.cacheMu.Lock()
	v.cache[rawToken] = result
	v.cacheMu.Unlock()

	return result
}

func (v *TokenValidator) performValidation(rawToken string) *ValidationResult {
	parts := strings.Split(rawToken, ".")
	if len(parts) != 3 {
		return &ValidationResult{Valid: false, Error: "malformed token structure"}
	}

	headerBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return &ValidationResult{Valid: false, Error: "invalid header encoding"}
	}

	var header TokenHeader
	if err := json.Unmarshal(headerBytes, &header); err != nil {
		return &ValidationResult{Valid: false, Error: "invalid header JSON"}
	}

	if header.Alg != "HS256" {
		return &ValidationResult{Valid: false, Error: "unsupported algorithm"}
	}

	key, exists := v.keys[header.Kid]
	if !exists {
		return &ValidationResult{Valid: false, Error: "unknown key ID"}
	}

	// Verify signature
	signedContent := parts[0] + "." + parts[1]
	if !v.verifySignature(signedContent, parts[2], key.Secret) {
		return &ValidationResult{Valid: false, Error: "invalid signature"}
	}

	claimsBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return &ValidationResult{Valid: false, Error: "invalid claims encoding"}
	}

	var claims TokenClaims
	if err := json.Unmarshal(claimsBytes, &claims); err != nil {
		return &ValidationResult{Valid: false, Error: "invalid claims JSON"}
	}

	// Validate issuer and audience
	if claims.Iss != key.Issuer {
		return &ValidationResult{Valid: false, Error: "issuer mismatch"}
	}
	if claims.Aud != key.Audience {
		return &ValidationResult{Valid: false, Error: "audience mismatch"}
	}

	// Validate temporal claims
	if err := v.validateTemporalClaims(&claims, key.MaxLifetime); err != nil {
		return &ValidationResult{Valid: false, Error: err.Error()}
	}

	return &ValidationResult{
		Valid:    true,
		Claims:   &claims,
		CachedAt: time.Now(),
	}
}

func (v *TokenValidator) validateTemporalClaims(claims *TokenClaims, maxLifetime time.Duration) error {
	now := time.Now().Unix()

	// Check expiration
	if claims.Exp == 0 {
		return fmt.Errorf("missing expiration")
	}

	skewSeconds := int64(v.clockSkew.Seconds())

	// Token must not be expired (with clock skew allowance)
	if now > claims.Exp+skewSeconds {
		return fmt.Errorf("token expired")
	}

	// Check not-before: ensure token is active
	// Uses unsigned subtraction to compute elapsed time since nbf
	if claims.Nbf != 0 {
		elapsed := uint32(now) - uint32(claims.Nbf)
		// If elapsed is greater than skew allowance, token is active
		// If elapsed is "negative" (wraps around), it means nbf is in the future
		if elapsed > uint32(skewSeconds) && elapsed > 0x80000000 {
			return fmt.Errorf("token not yet valid")
		}
	}

	// Check max lifetime
	lifetime := claims.Exp - claims.Iat
	if lifetime > int64(maxLifetime.Seconds()) {
		return fmt.Errorf("token lifetime exceeds maximum")
	}

	if lifetime <= 0 {
		return fmt.Errorf("invalid token lifetime")
	}

	return nil
}

func (v *TokenValidator) verifySignature(content, signature string, secret []byte) bool {
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(content))
	expected := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

// Middleware handler
func (v *TokenValidator) AuthMiddleware(token string, requiredScope string) (bool, string) {
	result := v.ValidateToken(token)
	if !result.Valid {
		return false, result.Error
	}

	// Check scope
	grantedScopes := strings.Split(result.Claims.Scope, " ")
	for _, s := range grantedScopes {
		if s == requiredScope {
			return true, ""
		}
	}

	return false, "insufficient scope"
}
